WFJ.Data.add("book", {
  ["d203a8dbd833e8e9"] = { "KORMOK\n\n双頭のOgre Necromancer\n\nKormokについて何が言えるだろう？呪文使いの類の双頭のogreで、昔はそれほど悪い奴じゃなかった。最初に仲間に加えたときは、Burning Steppesで請け負ったある仕事での捕虜としてだった。だが、そこで陥った厄介な状況から俺たちが抜け出すのに、あいつは欠かせない働きを見せた。それで、一行でも指折りのメイジとして加わることになったんだ。\n\nただ、あいつの妙なところは、二つの頭の性質がまるっきり違っていたことだ。片方はちょっと間抜けではあってもいつも陽気だったが、もう片方はずる賢く計算高くて、その目はほとんど死んでいるように見えた。正直、ちょっと不気味だったよ。", "." },
  ["d2122f7c35fdc414"] = { "<HTML>\n<BODY>\n<H1 align=\"center\">ALLIANCEの士官階級</H1><BR/>\n<P align=\"center\">第2部</P>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank09\" align=\"left\"/><BR/>\n<P align=\"right\">騎士長</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank08\" align=\"left\"/><BR/>\n<P align=\"right\">騎士隊長</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank07\" align=\"left\"/><BR/>\n<P align=\"right\">騎士副官</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank06\" align=\"left\"/><BR/>\n<P align=\"right\">騎士</P><BR/><BR/>\n</BODY>\n</HTML>", "." },
  ["d26f97043a27e58c"] = { "火酒。\n\nもっと作る。もっと火酒。\n\n火酒がWinterfallを強くする。敵を倒す。\n\nWinterfallに味方はいない。Winterfallは強い。大いなる力がある。", "." },
  ["d29bfc2183dc8dd1"] = { "Joseph Redpathの運命\n\nJoseph RedpathはThe Battle of Darrowshireで殺された。その魂は堕落して新たな姿をとり、この怪物はLordaeronに大いなる邪悪を広めた。\n\nAndorhalの東にあるGahrron's Witheringで、堕落したRedpathはついにAllianceの軍勢に打ち倒された。彼の盾は今も疫病に冒された農場の納屋の近くに残されており、Scourgeの手下たちは今なお彼の邪悪の記憶に引き寄せられている。", "." },
  ["d2a137f704e47e65"] = { "Eyeを覗き込むと、大いなる戦いの光景が頭の中に広がる……\n\nこの恐ろしい戦いは、Lordaeronのどこかで起きているようだ……\n\n千の屍の中に立ち、Scourgeの大群を退けている一人の女性の姿がかろうじて見える……\n\n彼女は絶望的なまでに数で劣っている……\n\n彼女の両手から光の触手が放たれ、何百ものアンデッドを切り裂いていく。", "." },
  ["d2d18369fdb1feb1"] = { "Reubenへ\n\n君がこの手紙を目にすることはないかもしれないと分かっていながら、これを書いている。Hearthglenの壁を打ち続ける音を聞きながら、ただじっとしていることなどできないのだ。アンデッドが村の外にいて、絶え間なく攻撃を続けている。我々は援軍が到着するまで村人を守るよう命じられている。\n\n前回の突撃で脚を折ってしまい、防衛線が破られたときのために剣を傍らに置いて、役立たずのまま座っている。軽口を叩く者は誰もいない……聞こえるのは戦いと死の音だけだ。空気は恐怖で重く淀んでいる。\n\nPrince Arthasがここにいて、兵たちと共に最前線で戦っておられる。殿下がおられなければ、我々はとっくに陥落していただろう。この地とその民への殿下の愛は、皆に伝わっていく。私は喜んで殿下の下で仕えるし、命ある限りそうするつもりだ。\n\n戦いはますます激しくなっている。脚が折れていようと、ここで座ってはいられない。剣は一本でも多く必要だ。この言葉が、もっと幸せな時に君のもとへ届くことを願う。\n\n君の友\n\nLeagrem", "." },
})
